#!/bin/sh
# generated by beerpowers v{{BEERPOWERS_VERSION}} — не править: обновляет /beerpowers:update
# Напоминание о скриншотах роли-тестера. Опция Q6 setup, по умолчанию выключена. Один скрипт
# на два события — регистрируется и на SubagentStart, и на SubagentStop, событие берётся из входа.
#
#   SubagentStart — записывает метку старта роли-тестера: файл
#                   .claude/.cache/screenshots-reminder/<session>/<agent_id>, его время и есть старт.
#   SubagentStop  — ищет скриншоты роли новее метки; не нашёл — один раз на роль за сессию
#                   возвращает её с выбором: снять скриншоты или строкой в отчёте назвать, почему
#                   их нет (exit 2, текст в stderr).
#
# Это не гейт. Нужны ли новые скриншоты, решает финальный reviewer по диффу и маршруту фикса:
# повторный заход тестера мог быть про тесты или API, а скриншоты прошлого захода остаются в силе,
# если фикс экран не менял. Хук этого различить не может, поэтому напоминание закрывается
# и скриншотами, и строкой «Скриншоты: не снимались — <причина>», которую reviewer сверяет с маршрутом.
#
# Аргументы, все необязательны:
#   --agent <subagent_type>  тип роли-тестера (по умолчанию testing-agent); другие роли хук пропускает
#   --prefix <префикс>       засчитываемые скриншоты — <префикс>-*.png|jpg|jpeg|webp; по умолчанию имя
#                            роли этого типа из таблицы «Состав» charter, не нашлось — tester
#   --dir <каталог>          явный каталог скриншотов вместо маски memory/tasks/*/screenshots/
#   --window <мин>           запасное окно свежести, когда метки старта нет (по умолчанию 180)
#
# Свежесть — «моложе старта этой роли», а не окно от момента проверки: скриншот прошлого захода
# той же задачи моложе трёх часов, но к текущему прогону отношения не имеет. Метки нет (хук
# старта не зарегистрирован или рантайм его не вызвал) — запасное окно в минутах, и текст
# напоминания говорит, что хук работал в запасном режиме.
#
# Правила хука с exit 2 на SubagentStop (reference/runtime-compat.md плагина):
#   1) в stderr — выполнимое ролью действие: этот текст роль принимает за следующую задачу,
#      поэтому он прямо говорит, что прежняя задача остаётся;
#   2) счётчик: без него роль, которой нечего снимать, не вышла бы из петли до конца сессии.
# Всё остальное — fail-soft: хук молчит и выпускает роль.

AGENT=testing-agent
PREFIX=
DIR=
WINDOW=180
while [ $# -gt 0 ]; do
  case "$1" in
    --agent) AGENT=$2; shift 2 ;;
    --prefix) PREFIX=$2; shift 2 ;;
    --dir) DIR=$2; shift 2 ;;
    --window) WINDOW=$2; shift 2 ;;
    *) shift ;;
  esac
done

cd "${CLAUDE_PROJECT_DIR:-.}" 2>/dev/null || exit 0
[ -f .claude/team-charter.md ] || exit 0

PAYLOAD=$(cat 2>/dev/null)
[ -n "$PAYLOAD" ] || exit 0
field() {
  printf '%s' "$PAYLOAD" | tr -d '\r\n' | sed -n "s/.*\"$1\"[[:space:]]*:[[:space:]]*\"\([^\"]*\)\".*/\1/p" | head -n 1
}

EVENT=$(field hook_event_name)
AGENT_TYPE=$(field agent_type)
AGENT_ID=$(field agent_id)
SESSION=$(field session_id)
[ "$AGENT_TYPE" = "$AGENT" ] || exit 0

case "$SESSION$AGENT_ID" in *[!A-Za-z0-9_.-]*) exit 0 ;; esac
STATE=".claude/.cache/screenshots-reminder/${SESSION:-nosession}"
mkdir -p "$STATE" 2>/dev/null || exit 0

if [ "$EVENT" = "SubagentStart" ]; then
  # Метка переписывается на каждом SubagentStart. Приходит ли он тиммейту на каждое новое
  # сообщение, а не только при подъёме, не замерено (reference/runtime-compat.md): если
  # не приходит, у тиммейта свежесть меряется от подъёма, и скриншот прошлого задания засчитается.
  [ -n "$AGENT_ID" ] && : > "$STATE/$AGENT_ID"
  exit 0
fi
[ "$EVENT" = "SubagentStop" ] || exit 0

if [ -z "$PREFIX" ]; then
  PREFIX=$(awk -F'|' -v agent="$AGENT" '
    /^## Состав/ { on = 1; next }
    on && /^## / { exit }
    on && /^\|/ {
      if (!col) { for (i = 1; i <= NF; i++) { c = $i; gsub(/[ `]/, "", c); if (c == "subagent_type") col = i }; next }
      c = $col; gsub(/[ `]/, "", c)
      if (c == agent) { r = $2; gsub(/[ `]/, "", r); print r; exit }
    }' .claude/team-charter.md 2>/dev/null)
  [ -n "$PREFIX" ] || PREFIX=tester
fi

if [ -n "$DIR" ]; then
  SEARCH=$DIR
  WHERE=$DIR
else
  SEARCH=memory/tasks
  WHERE="$SEARCH/<КОД>/screenshots/"
fi
[ -d "$SEARCH" ] || exit 0

MARK="$STATE/$AGENT_ID"
if [ -n "$AGENT_ID" ] && [ -f "$MARK" ]; then
  FRESH_TEST="-newer $MARK"
  MODE="моложе старта этого захода роли"
else
  FRESH_TEST="-mmin -$WINDOW"
  MODE="запасной режим: метки старта роли нет, окно $WINDOW мин"
fi

# Без --dir ищем по маске memory/tasks/*/screenshots/: фреймы Figma лежат в той же папке задачи
# (figma/) и с префиксом роли не совпадут, но путь отсекает и их.
SCREENSHOTS_ONLY='*/screenshots/*'
[ -n "$DIR" ] && SCREENSHOTS_ONLY='*'
# $FRESH_TEST без кавычек — намеренно: это два слова find (`-newer <файл>` / `-mmin -N`).
FRESH=$(find "$SEARCH" -type f -path "$SCREENSHOTS_ONLY" \
  \( -name "$PREFIX-*.png" -o -name "$PREFIX-*.jpg" -o -name "$PREFIX-*.jpeg" -o -name "$PREFIX-*.webp" \) \
  $FRESH_TEST 2>/dev/null | head -n 1)
[ -n "$FRESH" ] && exit 0

REMINDED="$STATE/${AGENT_ID:-noagent}.reminded"
[ -f "$REMINDED" ] && exit 0
: > "$REMINDED" 2>/dev/null

cat >&2 <<EOF
Напоминание о скриншотах, не новая задача: в $WHERE нет скриншотов $PREFIX-* ($MODE).
Скриншоты других ролей и макеты не в счёт.

Если в этом заходе ты проверял экраны — сохрани их скриншоты в <КОД>/screenshots/ задачи с именем
$PREFIX-<экран>-<ширина>.png (скилл beerpowers:page-screenshot, SCREENSHOT_TASK=<КОД>), открой каждый
через Read и опиши увиденное в отчёте.

Если экраны в этом заходе не проверялись — заход был про тесты, API или данные, либо скриншоты
прошлого захода в силе, потому что фикс экран не менял, — допиши в отчёт строку
«Скриншоты: не снимались — <причина>» и завершай. Повторно напоминание не сработает.
EOF
exit 2
